import{_ as n,c as t,o as i,ah as r}from"./chunks/framework.dGCgOE9J.js";const s="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_index.jpg",a="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_index_annotated.jpg",d="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_changelist.jpg",l="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_history.jpg",h="/Qonnectra-docs/pr-27/images/manual/teil-b/admin_delete_confirmation.jpg",k=JSON.parse('{"title":"20. Der Administrationsbereich","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-b-betrieb-admin-qgis/20-administrationsbereich.md","filePath":"manual/teil-b-betrieb-admin-qgis/20-administrationsbereich.md"}'),o={name:"manual/teil-b-betrieb-admin-qgis/20-administrationsbereich.md"};function u(c,e,b,g,m,p){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_20-der-administrationsbereich" tabindex="-1">20. Der Administrationsbereich <a class="header-anchor" href="#_20-der-administrationsbereich" aria-label="Permalink to &quot;20. Der Administrationsbereich&quot;">​</a></h1><p>Im <strong>Administrationsbereich</strong> pflegen Sie alles, was die Weboberfläche nicht anbietet: Konten und Rechte, Stammdaten, die Einstellungen eines Projekts, Kartendienste und die Systemprotokolle. Er ist eine eigene Anwendung neben der Weboberfläche, mit eigener Adresse und eigener Anmeldung.</p><p><img src="'+s+'" alt="Screenshot der Startseite des Administrationsbereichs mit der Liste aller Bereiche" data-zoomable="true"></p><h2 id="_20-1-zugang-aufbau-und-abgrenzung-zur-weboberflache" tabindex="-1">20.1 Zugang, Aufbau und Abgrenzung zur Weboberfläche <a class="header-anchor" href="#_20-1-zugang-aufbau-und-abgrenzung-zur-weboberflache" aria-label="Permalink to &quot;20.1 Zugang, Aufbau und Abgrenzung zur Weboberfläche&quot;">​</a></h2><p>Der Administrationsbereich hat eine eigene Adresse. Sie beginnt mit <code>admin.</code> statt mit <code>app.</code> und endet auf <code>/admin/</code>, etwa <code>https://admin.ihre-domain.de/admin/</code>. Die genaue Adresse Ihrer Installation nennt Ihnen die für den Betrieb zuständige Stelle, siehe Kapitel <a href="./28-betrieb-der-instanz.html">Betrieb der Instanz</a>.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Die Anmeldung der Weboberfläche gilt hier nicht. Sie melden sich im Administrationsbereich gesondert an, mit demselben Benutzernamen und Passwort. Hinein kommt nur ein Konto mit „Mitarbeiter-Status“, und arbeiten kann darin in der Praxis nur das Superuser-Konto, siehe Abschnitt <a href="./19-rollen-und-rechte.html#_19-4-superuser-gegenuber-gruppenmitgliedschaft">Superuser gegenüber Gruppenmitgliedschaft</a>.</p></div><p>Die Startseite listet alle Bereiche. Der Kasten „Neueste Aktionen“ daneben zeigt nur Ihre eigenen Änderungen im Administrationsbereich, nicht die anderer Konten.</p><p><img src="'+a+'" alt="Screenshot der Startseite des Administrationsbereichs mit Beschriftung der Kopfzeile oben, der Sprachauswahl oben rechts, der Bereichsliste links und des Kastens „Neueste Aktionen“ daneben" data-zoomable="true"></p><p>Auf allen übrigen Seiten steht die Bereichsliste links am Rand, als Navigationsleiste des Administrationsbereichs.</p><p>Fast alles steht unter der Überschrift „Api“, Konten und Gruppen unter „Authentifizierung und Autorisierung“. Die Blöcke „Auth Token“ und „Token Blacklist“ verwaltet Qonnectra selbst; dort ist nichts zu tun.</p><p>Die Namen der Bereiche weichen teils von den Begriffen der Weboberfläche und dieses Handbuchs ab:</p><table tabindex="0"><thead><tr><th>Administrationsbereich</th><th>Weboberfläche und Handbuch</th></tr></thead><tbody><tr><td>„Gräben“</td><td>Trassen</td></tr><tr><td>„Feature-Dateien“</td><td>Anhänge</td></tr><tr><td>„Wohnungseinheiten“, „Wohnungseinheit-Typen“, „Wohnungseinheit-Status“</td><td>Wohneinheiten mit Typ und Status</td></tr><tr><td>„Bau-/Verlegearten“</td><td>Bauart einer Trasse</td></tr><tr><td>„Netzwerkschema“</td><td>Netzschema-Einstellungen, siehe Abschnitt <a href="./22-projektbezogene-konfiguration.html#_22-1-netzschema-einstellungen">Netzschema-Einstellungen</a></td></tr><tr><td>„Rohrverzweigung“</td><td>Rohrabzweig-Einstellungen, siehe Abschnitt <a href="./22-projektbezogene-konfiguration.html#_22-2-einstellungen-der-rohrverzweigung">Einstellungen der Rohrverzweigung</a></td></tr><tr><td>„Wertermittlungssätze“</td><td>Kostensätze der Wertermittlung</td></tr><tr><td>„WMS-Layer“</td><td>externe Kartendienste, Modellname <code>wmssource</code> (die Quelle, nicht der einzelne Layer), siehe Abschnitt <a href="./27-qgis-server-und-kartendienste.html#_27-4-externe-wms-quellen-als-hintergrund-einbinden">Externe WMS-Quellen</a></td></tr><tr><td>„Leitungsauskünfte“, „Leitungsauskunftsbereiche“</td><td>Auskünfte und Auskunftsbereiche</td></tr><tr><td>„Modell-Zugriffsrechte“, „Seiten-Zugriffsrechte“</td><td>Modell- und Routenrechte, siehe Kapitel <a href="./19-rollen-und-rechte.html">Rollen und Rechte</a></td></tr></tbody></table><p>Die Oberfläche ist überwiegend deutsch. Einzelne Feldnamen, Hilfetexte und Beschriftungen stehen auf Englisch, weil sie nicht übersetzt sind, etwa „area type“ im Formular eines Gebiets, „Changes“ im Änderungsverlauf oder „Reset password“ im Formular eines Kontos; die Sprachauswahl in der Kopfzeile ändert daran nichts.</p><h2 id="_20-2-suchen-filtern-und-massenbearbeitung" tabindex="-1">20.2 Suchen, Filtern und Massenbearbeitung <a class="header-anchor" href="#_20-2-suchen-filtern-und-massenbearbeitung" aria-label="Permalink to &quot;20.2 Suchen, Filtern und Massenbearbeitung&quot;">​</a></h2><p>Jeder Bereich öffnet eine Liste. Ihre Bedienelemente:</p><ul><li>Suchfeld über der Liste – durchsucht je nach Bereich andere Spalten, bei den Rohren etwa den Namen. Nicht jede Liste hat eines.</li><li>Filter rechts – grenzen die Liste auf einen Wert ein; mehrere Filter wirken zusammen.</li><li>„Aktion“ über der Liste – führt eine Aktion für die angehakten Zeilen aus.</li></ul><p><img src="'+d+'" alt="Screenshot der Rohrliste im Administrationsbereich mit Beschriftung der Bereichsliste links, des Suchfelds oben, der Aktionsauswahl darunter, der Auswahlspalte links in der Tabelle und der Filter rechts" data-zoomable="true"></p><p>Eine Aktion führen Sie so aus:</p><ol><li>Haken Sie die Zeilen an, für die sie gelten soll. Der Haken in der Kopfzeile wählt alle Zeilen der Seite.</li><li>Wählen Sie die Aktion im Feld „Aktion“.</li><li>Klicken Sie auf „Ausführen“.</li></ol><p>Neben „… löschen“ bieten einige Bereiche Aktionen, die Daten nachträglich in Ordnung bringen. Sie sind für die Fälle gedacht, in denen Daten an der Weboberfläche vorbei entstanden sind, etwa in QGIS oder durch einen Import:</p><table tabindex="0"><thead><tr><th>Bereich</th><th>Aktion</th><th>Wirkung</th></tr></thead><tbody><tr><td>„Rohre“</td><td>„Mikrorohre für ausgewählte Rohre erstellen (nur wenn keine vorhanden sind)“</td><td>legt die Mikrorohre nach dem Rohrtyp an</td></tr><tr><td>„Kabel“</td><td>„Fasern für ausgewählte Kabel erstellen (nur wenn keine vorhanden sind)“</td><td>legt die Fasern nach dem Kabeltyp an</td></tr><tr><td>„Kabel“</td><td>„Kabellänge für ausgewählte Kabel neu berechnen“ und „Kabellänge für alle Kabel mit aktuellen Filtern neu berechnen“</td><td>berechnet die Kabellänge aus den verknüpften Mikrorohren neu</td></tr><tr><td>„Gräben“</td><td>„Erstelle neue IDs für Trassen mit alten Formaten“</td><td>vergibt Trassen-IDs im aktuellen Format</td></tr><tr><td>„Netzknoten“</td><td>„Verknüpfe Kabel automatisch mit Mikrorohren (Adressbasiert)“</td><td>verknüpft die Kabel an den gewählten Netzknoten mit den Mikrorohren ihrer Adressen</td></tr><tr><td>„Feature-Dateien“</td><td>Verschieben und Löschen verwaister Dateien</td><td>siehe Abschnitt <a href="./23-dateien-und-anhaenge.html#_23-5-verwaiste-dateien-finden-verschieben-und-loschen">Verwaiste Dateien</a></td></tr><tr><td>„Log-Einträge“</td><td>Löschen markierter oder aller gefilterten Einträge</td><td>siehe Kapitel <a href="./28-betrieb-der-instanz.html">Betrieb der Instanz</a></td></tr><tr><td>„WMS-Layer“</td><td>„Empfohlene Einstellungen scannen und anwenden“</td><td>siehe Abschnitt <a href="./27-qgis-server-und-kartendienste.html#_27-4-externe-wms-quellen-als-hintergrund-einbinden">Externe WMS-Quellen</a></td></tr></tbody></table><p>Die beiden Aktionen „… erstellen (nur wenn keine vorhanden sind)“ überspringen jedes Rohr und jedes Kabel, das schon Mikrorohre oder Fasern hat. Ein unvollständiger Satz wird nicht ergänzt.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>„Kabellänge für alle Kabel mit aktuellen Filtern neu berechnen“ wirkt auf die ganze gefilterte Liste, nicht nur auf die angehakten Zeilen und nicht nur auf die angezeigte Seite. Ohne Filter sind das alle Kabel der Installation. Dasselbe gilt für das Löschen aller gefilterten Log-Einträge.</p></div><p>Einige Listen lassen Werte direkt in der Zeile ändern, etwa die Zugriffsebene der Modell-Zugriffsrechte oder die Reihenfolge der Container-Typen. Solche Änderungen speichern Sie mit „Sichern“ unter der Liste.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ohne „Sichern“ gehen in der Liste geänderte Werte beim Verlassen der Seite ohne Warnung verloren.</p></div><h2 id="_20-3-anderungsverlauf-eines-objekts-einsehen" tabindex="-1">20.3 Änderungsverlauf eines Objekts einsehen <a class="header-anchor" href="#_20-3-anderungsverlauf-eines-objekts-einsehen" aria-label="Permalink to &quot;20.3 Änderungsverlauf eines Objekts einsehen&quot;">​</a></h2><p>Für die Fachobjekte – Trassen, Rohre, Mikrorohre, Kabel, Netzknoten, Adressen, Wohneinheiten, Gebiete – sowie für Projekte, Kennzeichen, Container-Typen, Auskünfte und Auskunftsbereiche speichert Qonnectra jede Änderung. Den Verlauf öffnen Sie im Formular des Objekts oben rechts mit „Geschichte“.</p><p><img src="'+l+'" alt="Screenshot der Änderungsgeschichte eines Rohrs mit Hervorhebung der Liste der Versionen oben im Inhaltsbereich" data-zoomable="true"></p><p>Die Liste nennt je Version den Zeitpunkt, die Art der Änderung („Kommentar“), das Konto („Geändert von“) und unter „Changes“ die geänderten Felder mit altem und neuem Wert. Ein Klick auf eine Version zeigt alle ihre Werte; von dort lässt sie sich wiederherstellen.</p><p>Auch Änderungen über die Weboberfläche stehen im Verlauf, mit dem Konto, das sie vorgenommen hat.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Der Verlauf beginnt mit der ersten Änderung, die Qonnectra aufgezeichnet hat. Objekte, die aus einem Import stammen und seitdem nicht geändert wurden, zeigen „Dieses Objekt hat keine Änderungshistorie.“ Änderungen, die in QGIS direkt in der Datenbank vorgenommen werden, erscheinen nicht im Verlauf, siehe Kapitel <a href="./26-netzdaten-in-qgis-bearbeiten.html">Netzdaten in QGIS bearbeiten</a>.</p></div><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Das Wiederherstellen überschreibt die aktuellen Werte des Objekts mit dem Stand der gewählten Version. Verbindungen zu anderen Objekten – die Mikrorohre eines Rohrs, die Rohrzuordnung, die Fasern eines Kabels – stellt es nicht wieder her. Ein gelöschtes Objekt kommt damit nicht samt seinem Umfeld zurück.</p></div><h2 id="_20-4-was-im-administrationsbereich-nicht-gepflegt-werden-sollte" tabindex="-1">20.4 Was im Administrationsbereich nicht gepflegt werden sollte <a class="header-anchor" href="#_20-4-was-im-administrationsbereich-nicht-gepflegt-werden-sollte" aria-label="Permalink to &quot;20.4 Was im Administrationsbereich nicht gepflegt werden sollte&quot;">​</a></h2><p>Der Administrationsbereich zeigt zu jedem Fachobjekt ein Formular mit allen Feldern. Dass ein Feld dort steht, heißt nicht, dass es dort gepflegt werden sollte:</p><ul><li><strong>Geometrien</strong> – Trassen, Netzknoten, Adressen und Gebiete zeichnen Sie in QGIS, siehe Kapitel <a href="./26-netzdaten-in-qgis-bearbeiten.html">Netzdaten in QGIS bearbeiten</a>.</li><li><strong>Fachdaten, die die Weboberfläche bearbeitet</strong> – Rohre, Kabel, Wohneinheiten, Auskünfte. Die Weboberfläche prüft Eingaben, die das Formular hier nicht prüft, und legt abhängige Daten passend an.</li><li><strong>IDs, UUIDs und berechnete Felder</strong> wie Länge oder Trassen-ID. Qonnectra setzt sie selbst.</li></ul><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Löschen nimmt abhängige Objekte mit, hier wie in der Weboberfläche. Ein gelöschtes Rohr etwa nimmt seine Mikrorohre, seine Rohrzuordnung und die Verknüpfungen zu Kabeln mit. Die Rückfrage der Weboberfläche nennt davon höchstens die Rohrzuordnung; die Bestätigungsseite hier listet alles auf, was mitgelöscht wird. Lesen Sie die Liste, bevor Sie bestätigen – rückgängig machen lässt sich das Löschen nur über eine Sicherung, siehe Kapitel <a href="./28-betrieb-der-instanz.html">Betrieb der Instanz</a>.</p></div><p><img src="'+h+'" alt="Screenshot der Bestätigungsseite beim Löschen eines Rohrs mit der Zusammenfassung der mitgelöschten Mikrorohre, Rohrzuordnungen und Verknüpfungen oben und der Liste der einzelnen Objekte darunter" data-zoomable="true"></p>',37)])])}const z=n(o,[["render",u]]);export{k as __pageData,z as default};
